:root { --scale: 1; --motion: 120ms; --dock: #0e5c63; --tap: 44px; }
body { font-size: calc(13px * var(--scale)); color: var(--dock); transition: opacity var(--motion); }
button, .btn, input, .input, textarea, select, .select, .linkBtn, .rail__link { min-height: var(--tap); }

